PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE pengaturan (
            kunci TEXT PRIMARY KEY,
            nilai TEXT NOT NULL DEFAULT ""
        );
CREATE TABLE user (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT NOT NULL UNIQUE,
            nama TEXT NOT NULL DEFAULT "",
            password_hash TEXT NOT NULL,
            role TEXT NOT NULL,
            aktif INTEGER NOT NULL DEFAULT 1,
            updated_at TEXT NOT NULL DEFAULT "",
            failed_count INTEGER NOT NULL DEFAULT 0,
            locked_until TEXT NULL
        );
CREATE TABLE sesi (
            token_hash TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            created_at TEXT NOT NULL DEFAULT "",
            expires_at TEXT NOT NULL DEFAULT "",
            last_seen TEXT NOT NULL DEFAULT ""
        );
CREATE TABLE kode_antrian (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kode TEXT NOT NULL UNIQUE,
            nama TEXT NOT NULL DEFAULT "",
            urutan INTEGER NOT NULL DEFAULT 0,
            aktif INTEGER NOT NULL DEFAULT 1,
            reset_mode TEXT NOT NULL DEFAULT "harian",
            warna TEXT NOT NULL DEFAULT "#0d9488",
            updated_at TEXT NOT NULL DEFAULT ""
        );
CREATE TABLE tiket (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            kode TEXT NOT NULL,
            nomor INTEGER NOT NULL,
            kode_tiket TEXT NOT NULL,
            tanggal TEXT NOT NULL,
            periode TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT "RESEP_MASUK",
            keterangan TEXT NOT NULL DEFAULT "",
            created_at TEXT NOT NULL DEFAULT "",
            siap_at TEXT NULL,
            called_at TEXT NULL,
            called_count INTEGER NOT NULL DEFAULT 0,
            diambil_oleh TEXT NOT NULL DEFAULT "",
            dilayani_oleh TEXT NOT NULL DEFAULT "",
            updated_at TEXT NOT NULL DEFAULT ""
        , token TEXT NOT NULL DEFAULT "", first_called_at TEXT NULL, no_rm TEXT NOT NULL DEFAULT "", nama_pasien TEXT NOT NULL DEFAULT "", recall_at TEXT NULL);
CREATE TABLE tiket_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            tiket_id INTEGER NOT NULL,
            status TEXT NOT NULL DEFAULT "",
            waktu TEXT NOT NULL DEFAULT "",
            oleh TEXT NOT NULL DEFAULT "",
            catatan TEXT NOT NULL DEFAULT ""
        );
CREATE TABLE nomor_counter (
            kode TEXT NOT NULL,
            periode TEXT NOT NULL,
            nomor INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (kode, periode)
        );
CREATE TABLE simrs_permintaan (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            no_rm TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT "menunggu",
            nama TEXT NOT NULL DEFAULT "",
            tgl_lahir TEXT NOT NULL DEFAULT "",
            jenis_kelamin TEXT NOT NULL DEFAULT "",
            pesan TEXT NOT NULL DEFAULT "",
            oleh TEXT NOT NULL DEFAULT "",
            created_at TEXT NOT NULL DEFAULT "",
            selesai_at TEXT NULL
        );
CREATE TABLE log_admin (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            waktu TEXT NOT NULL DEFAULT "",
            oleh TEXT NOT NULL DEFAULT "",
            aksi TEXT NOT NULL DEFAULT "",
            rincian TEXT NOT NULL DEFAULT ""
        );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_tiket_tanggal ON tiket (tanggal, kode);
CREATE INDEX idx_tiket_status ON tiket (tanggal, status);
CREATE INDEX idx_tiket_kode_tiket ON tiket (tanggal, kode_tiket);
CREATE INDEX idx_tiket_periode ON tiket (periode, kode);
CREATE INDEX idx_tiket_log ON tiket_log (tiket_id, id);
CREATE INDEX idx_tiket_token ON tiket (token);
CREATE INDEX idx_simrs_status ON simrs_permintaan (status, id);
CREATE INDEX idx_simrs_created ON simrs_permintaan (created_at);
CREATE INDEX idx_log_admin_waktu ON log_admin (waktu);
COMMIT;
