INSERT INTO pengaturan VALUES('pengumuman_template','[{"id":5,"nama":"Pengumuman 5","teks":"Panggilan kepada pemilik mobil. Toyota Avanza warna putih dengan nomor polisi. DP 1 3 4 2 GF. Mohon kesediaannya untuk memindahkan kendaraan Anda karena menghalangi kendaraan lain. Terima kasih","oleh":"petugaspanggil","waktu":"2026-10-08 13:56:09"},{"id":3,"nama":"PENGUMUMAN 2 (Tentang Barcode)","teks":"Sekedar informasi, lembar tiket yang ada di tangan anda saat ini terdapat barcode unik. scan menggunakan kamera smartphone untuk mengetahui status kesiapan obat anda,\r\ndengan begitu, anda dapat memantau status kesiapan obat dimanapun anda berada tanpa harus menunggu didepan apotik. \r\napabila tiket anda hilang, cukup perlihatkan nomor tiket pada layar HP anda kepada petugas saat menerima obat.","oleh":"superadmin","waktu":"2026-10-07 11:30:15"},{"id":2,"nama":"SELAMAT DATANG","teks":"Selamat Datang di Rumah Sakit Andi jemma Masamba.\r\nKepada Bapak Ibu pasien yang terhormat, mohon untuk tetap tertib dan menunggu panggilan sesuai nomor tiket yang telah diperoleh.\r\nKami mohon kesabarannya selama proses penyiapan obat. Petugas kami akan memberikan pelayanan sebaik mungkin.\r\nTerima kasih atas kesabaran, pengertian, dan kepercayaan Anda kepada Apotik RSUD Andi jemma Masamba.Salam Seh","oleh":"superadmin","waktu":"2026-10-07 10:07:39"},{"id":1,"nama":"PENGUMUMAN 1 (Tentang Urutan Tiket)","teks":"Assalamualaikum dan selamat pagi, disampaikan kepada bapak dan ibu, bahwa pelayanan apotik memanggil tiket bukan berdasarkan nomor urut tiket, tapi menyesuaikan penyiapan berdasarkan jumlah obat dan waktu racikan obat. hal ini merupakan salah satu upaya untuk bantu mengurangi waktu tunggu pasien dan meminimalisir penumpukan resep. Atas perhatian dan kerja samanya, kami ucapkan terima kasih.","oleh":"superadmin","waktu":"2026-10-07 10:00:25"}]');
